{
  "technical_and_design_decisions": [
    "Reuse the existing acceptance-test patterns of the Spring Cloud Stream app-starters/stream-applications codebase: each module is exercised end-to-end by deploying a test stream (source -> module under test -> verification sink) with an embedded/test binder rather than testing classes in isolation.",
    "Write tests in Java 17 with JUnit 5, Spring Boot Test, AssertJ, and Awaitility for asynchronous assertions on message flow.",
    "Use embedded test doubles/containers for external systems: GreenMail (embedded SMTP) for the mail sink, a Redis container (Testcontainers) or in-memory store for aggregate-counter and field-value-counter sinks, and a Hadoop MiniDFSCluster (or local filesystem fallback) for the hdfs-dataset sink.",
    "For each module, cover at minimum: default-configuration happy path, key configuration properties, and one representative error/edge scenario; keep scenarios deterministic to avoid flaky CI results.",
    "Wire the new test suites into the existing CI pipeline via a dedicated Maven/Gradle profile executed during the verify stage so coverage runs on every build.",
    "No production (module) code changes are planned; if a test exposes a genuine defect, only minimal test-side workarounds are applied and the defect is reported separately."
  ],
  "assumptions": [
    "The nine target modules (json-tuple, script, scripts, splitter processors; gauge, aggregate-counter, field-value-counter, hdfs-dataset, mail sinks) already exist and are functionally complete; this increment adds only acceptance test coverage.",
    "An existing acceptance-test framework/infrastructure from other modules in the repository is available to reuse (base classes, test binder, stream deployment utilities).",
    "The CI environment supports running Docker (for Testcontainers) or equivalent embedded services, and the pipeline can be modified to include the new tests.",
    "One developer performs all work; estimates express total effort in workdays (8 hours/day), not elapsed calendar time.",
    "Estimates include test design, implementation, local execution, debugging, and stabilization, but exclude fixing any production defects discovered.",
    "Build baseline is Spring Framework 6.x / Spring Boot 3.x on Java 17, consistent with the referenced platform.",
    "Source/sink apps needed to build test streams (e.g., test source, log sink) are already available in the project."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Analysis and test strategy definition",
      "activity_description": "Study the nine target modules (functionality, configuration properties, inputs/outputs), review existing acceptance-test patterns in the repository, and define the concrete test scenarios and coverage matrix per module (U1-U8).",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A2",
      "activity_name": "Shared test harness and fixtures setup",
      "activity_description": "Implement/reuse shared acceptance-test infrastructure: base test classes, test-stream deployment helpers, Awaitility-based async assertion utilities, GreenMail embedded SMTP fixture, Redis container fixture, and MiniDFSCluster/HDFS fixture used by the sink tests.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A3",
      "activity_name": "json-tuple processor acceptance tests (U1)",
      "activity_description": "Implement acceptance tests validating that the json-tuple processor converts JSON payloads into tuples: default mapping, nested fields, custom configuration, and malformed-input handling.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A4",
      "activity_name": "script processor acceptance tests (U2, part 1)",
      "activity_description": "Implement acceptance tests validating the script processor: inline and external script evaluation, script language configuration, payload transformation, and script error behavior.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A5",
      "activity_name": "scripts processor acceptance tests (U2, part 2)",
      "activity_description": "Implement acceptance tests validating the scripts processor variant, covering its configuration properties and expected message transformations, including failure cases.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A6",
      "activity_name": "splitter processor acceptance tests (U3)",
      "activity_description": "Implement acceptance tests validating the splitter processor: splitting payloads into multiple messages, delimiter/expression-based splitting, charset and ordering-related properties, and edge cases.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A7",
      "activity_name": "gauge sink acceptance tests (U4)",
      "activity_description": "Implement acceptance tests validating the gauge sink: metric publication with default and custom metric names, expression-based value extraction, and verification that metric values are recorded correctly.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A8",
      "activity_name": "aggregate-counter sink acceptance tests (U5)",
      "activity_description": "Implement acceptance tests validating the aggregate-counter sink against Redis/in-memory store: counter increments, time-bucketed aggregation and windowing properties, and persistence verification.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A9",
      "activity_name": "field-value-counter sink acceptance tests (U6)",
      "activity_description": "Implement acceptance tests validating the field-value-counter sink against Redis: field value extraction from payloads, per-value count increments, and querying/verifying stored counts.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A10",
      "activity_name": "hdfs-dataset sink acceptance tests (U7)",
      "activity_description": "Implement acceptance tests validating the hdfs-dataset sink using a MiniDFSCluster fixture: dataset file creation and partitioning, record formatting, rollover behavior, and verification of written dataset contents.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "A11",
      "activity_name": "mail sink acceptance tests (U8)",
      "activity_description": "Implement acceptance tests validating the mail sink using an embedded GreenMail SMTP server: message-to-email mapping (to/subject/body), content-type handling, and verification of delivered emails.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A12",
      "activity_name": "CI pipeline integration and validation",
      "activity_description": "Integrate all new acceptance-test suites into the CI build (dedicated profile/stage), verify they execute on every build, and confirm reporting of results and artifacts.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A13",
      "activity_name": "Stabilization, code review, and rework",
      "activity_description": "Run the full suites repeatedly to detect and eliminate flaky behavior (timeouts, async races), address code review feedback, and refactor shared utilities as needed.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A14",
      "activity_name": "Documentation",
      "activity_description": "Document the new acceptance tests: coverage per module, how to run them locally and in CI, and required test fixtures/services.",
      "most_likely_effort": 0.5
    }
  ],
  "reported_total": {
    "most_likely_effort": 22.5
  }
}

